window.__BUNDLE__={"generatedAt":"2026-08-25T04:14:56.763727+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-18","archiveCutoff":"2021-08-26","addedToday":129,"addedThisRun":129,"fetchStats":{"hf":194,"arxiv":1221,"total":1415},"freshness":{"latestPaperDate":"2026-08-25","latestPublishedDate":"2026-08-25","latestBatchCount":461,"newInLast24h":525,"newInLast48h":775},"historyTotal":8732,"topicCounts":{"Multi-Agent":1666,"Evaluation":4407,"Planning":802,"Memory":198,"Code Agent":461,"Interpretability":298,"Agentic RAG":918,"Agentic Search":1110,"RL for LLM":685,"Reasoning":2782,"Hallucination":543,"Post-Training":1273,"Alignment":1155,"World Model":93,"Tool Use":1000,"Agent Safety":1958,"Computer Use":197,"Reflection":390,"VLM Training":395,"LLM Training":936,"Fine-tuning":1259,"Multimodal Agent":56,"Agent Framework":608,"Error Attribution":79,"Data Engine":192},"count":36,"recentTotal":1736,"archiveCount":0,"archiveTotal":6996,"sources":{"hf":58,"arxiv":1674,"semanticScholar":4},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"date":"2026-08-25","upvotes":10,"tags":["Planning","World Model"],"topics":["Planning","World Model"],"authors":["Zhiyang Deng","Boran Zhang","Danze Chen","Yeying Jin"],"source":"hf","id":"arxiv:2608.21439","hfUrl":"https://huggingface.co/papers/2608.21439","submittedDate":"2026-08-18","arxiv":"https://arxiv.org/abs/2608.21439","url":"https://arxiv.org/abs/2608.21439","pdf":"https://arxiv.org/pdf/2608.21439.pdf","announceDate":"2026-08-25","title":"WorldMind: Decoupled Game World Model for State-Aware NPC Behavior","abstract":"Game world models have recently demonstrated promising capabilities in generating visually coherent and action-controllable gameplay videos. However, non-player character (NPC) behavior in existing models is either implicitly entangled with video generation or explicitly prescribed through external control signals. Consequently, a game world model has to jointly understand the state, plan the NPC's response and render its visual outcome, limiting its ability to produce responsive and state-aware NPC behavior. The challenge lies in the lack of an explicit interface for state-grounded decision-making. To this end, we introduce WorldMind, to our knowledge the first decoupled framework for state-aware NPC behavior in game world models. WorldMind separates interactive world modeling into four layers: an Understanding Layer that constructs a compact state from generated frames; a Decision Laye"},{"date":"2026-08-25","upvotes":108,"tags":["Planning"],"topics":["Planning"],"authors":["Apodex Team","B. An","B. Li","B. Wang","B. Zhang","B. L. Wang","C. Feng","C. Wei","C. Xue","C. Zhang","D. Ng","D. Ye","E. Min","F. Chen","F. Liu","F. Yang","F. Ye","H. Xu","H. Yang","H. Ye","H. Zhang","H. Zhao","J. Li","J. Lin","J. Xia","K. Jin","K. Wang","K. Yang","L. Bing","L. Lei","L. Su","Le. Wang","Lu. Wang","N. Wang","Q. Ren","Q. Yang","R. Li","S. Bai","S. Du","S. Li","S. Lin","S. Nie","S. Wang","S. Zhang","S. Z. Wang","Ta. Q. Fang","Ti. Q. Fang","W. Fang","W. Li","W. Zhang","X. Chen","X. Li","X. Tang","X. Wang","X. Xu","X. Zhang","X. Q. Wang","X. Y. Wang","Y. Deng","Y. Gao","Y. Hu","Y. Li","Y. Sui","Y. Wang","Y. Xiao","Y. Zhang","Z. Chen","Z. Cheng","Z. Feng","Z. Liang","Z. Zhang"],"source":"arxiv","id":"arxiv:2608.23283","hfUrl":"https://huggingface.co/papers/2608.23283","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23283","url":"https://arxiv.org/abs/2608.23283","pdf":"https://arxiv.org/pdf/2608.23283.pdf","announceDate":"2026-08-25","title":"Apodex 1.1: Scaling Agentic Intelligence for Complex Work","abstract":"General-purpose language models can reason and synthesize knowledge, but complex work also requires sustained interaction with files, information sources, and executable code, together with state maintenance, failure recovery, and verifiable delivery. We call this \\emph{working capability}: sustained, verifiable progress toward a real-world objective. Apodex 1.1 develops this capability along two complementary dimensions. \\emph{Environment Scaling} expands the diversity and verifiability of executable file, search, and code environments, while \\emph{Agentic Coordination Scaling} trains agents to decompose long-horizon tasks, delegate parallel work, integrate asynchronous results, and replan. A shared execution harness and AgentOS maintain task state and provenance across tools and agents, and training turns environment trajectories and coordination traces into reliable behavior. Across c"},{"date":"2026-08-25","upvotes":9,"tags":["Multi-Agent","Evaluation"],"topics":["Multi-Agent","Evaluation"],"authors":["Seth Karten","Alex L. Zhang","Kevin Thomas","Sebastian Müller","Elie Bakouch","Daniel Auras","Mika Senghaas","Fares Obeid","Konstantin Dunas","Johannes Hagemann","Sami Jaghouar"],"source":"arxiv","id":"arxiv:2608.23552","hfUrl":"https://huggingface.co/papers/2608.23552","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23552","url":"https://arxiv.org/abs/2608.23552","pdf":"https://arxiv.org/pdf/2608.23552.pdf","announceDate":"2026-08-25","title":"Prime Agent: A Self-Improving RLM Harness","abstract":"Language models are sequential processors, but long-horizon agency requires external information and computation beyond model weights and active context. Prime Agent is an open-source harness for long-horizon evaluation and coding-agent workflows. A persistent IPython REPL follows the Recursive Language Model abstraction for programmatic context processing and test-time compute, while Continual Harness preserves histories, memories, skills, prompts, and subagent specifications across trajectories. Recursive subagents coordinate through direct agent-to-agent communication, and the Agents View lets humans inspect and manage daemon-backed sessions. Prime Agent standardizes execution, recovery, verification, and resource accounting while leaving strategy construction to the model. This low-friction, expressive membrane prevents harness failures from becoming model failures and pushes measure"},{"date":"2026-08-25","upvotes":2,"tags":["Code Agent","Evaluation"],"topics":["Code Agent","Evaluation"],"authors":["Kun Chen","Haorong Hong","Peizhong Gao","Jianfeng Lin","Tongxu Luo","Yuxuan Xie","Chenxu Liu","Jieling He","Zhongyuan Liu","Zeno Zeng"],"source":"arxiv","id":"arxiv:2608.21833","hfUrl":"https://huggingface.co/papers/2608.21833","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21833","url":"https://arxiv.org/abs/2608.21833","pdf":"https://arxiv.org/pdf/2608.21833.pdf","announceDate":"2026-08-25","title":"GameXpert-Bench: How Far Are Coding Agents from Expert Game Development?","abstract":"Recent large language models (LLMs) can operate as coding agents that build complete games from natural language requests. Game development is especially demanding because program logic, visual and audio content, interfaces, interaction and playability must function together in one executable artifact. Measuring this capability therefore requires evaluation of both game product and the development process. Existing benchmarks often assess the game development capabilities of LLMs by evaluating the final artifact or an isolated development stage. Our analysis of complete human-agent development trajectories identifies three stages that together span the lifecycle of game development with a coding agent: initial game generation, bug diagnosis and repair, and optimization over multiple turns. Therefore, we introduce GameXpert-Bench, which operationalizes the three lifecycle stages as three "},{"date":"2026-08-25","upvotes":2,"tags":["Agentic Search"],"topics":["Agentic Search"],"authors":["Jingjie Ning","Xueqi Li"],"source":"arxiv","id":"arxiv:2608.22856","hfUrl":"https://huggingface.co/papers/2608.22856","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.22856","url":"https://arxiv.org/abs/2608.22856","pdf":"https://arxiv.org/pdf/2608.22856.pdf","announceDate":"2026-08-25","title":"Same Agent, Different Answers: A Repeat-Aware Audit of Corpus-Induced Answer Churn in Retrieval-Augmented QA","abstract":"A retrieval-augmented QA system can return different answers after an index expansion even when its requested model identifier, prompt, retrieval policy, evidence depth, rendering, and exposed generation controls are held fixed. Aggregate accuracy may hide these changes when gains and losses cancel, while ordinary generation variability makes one-shot comparisons overstate update effects. We call the hidden phenomenon accuracy-blind answer churn and introduce the \\emph{Snapshot Compatibility Audit}, which estimates excess answer churn by subtracting same-snapshot repeat disagreement from cross-snapshot disagreement. We instantiate it by expanding one frozen FineWeb prefix from one to seven shards. In a preregistered 400-question Natural Questions study, normalized-exact and blinded-semantic excess churn are 6.44 and 10.25 percentage points while exact-match accuracy changes by only $-1.5"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","Reflection"],"authors":["Jialong Liu","Yuling Shi","Ning Yang","Xiaodong Gu","Zuchao Li"],"source":"arxiv","id":"arxiv:2608.23493","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23493","url":"https://arxiv.org/abs/2608.23493","pdf":"https://arxiv.org/pdf/2608.23493.pdf","announceDate":"2026-08-25","title":"SRPO: Self-Reflective Policy Optimization for Long-Horizon Reasoning","abstract":"Self-reflection is a powerful mechanism for credit assignment in human learning, converting sparse outcome feedback into actionable guidance. However, its potential for post-training Large Language Models (LLMs) remains underexplored. We propose Self-Reflective Policy Optimization (SRPO), a framework that internalizes this capability. SRPO enables LLMs to analyze their own completed trajectories, synthesize errors into concise \"reflection patches,\" and use reflection-conditioned teacher scores on student on-policy rollouts as dense token-level training signals. This process effectively transforms sparse terminal supervision into dense, token-level learning signals without requiring external critics, separate reward models, or larger teacher models. We demonstrate that SRPO achieves state-of-the-art performance across mathematical reasoning and long-horizon agentic benchmarks with excepti"},{"date":"2026-08-25","upvotes":0,"tags":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Evaluation"],"topics":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Evaluation","RL for LLM"],"authors":["Jun Chen","Yongchao Liu","Pengyu Qiu","Jiajun Zheng","Juelu Zhang","Yujie Zeng","Qin Zhang","Ziyue Qiao","Xiao Luo"],"source":"arxiv","id":"arxiv:2608.22479","submittedDate":"2026-08-23","arxiv":"https://arxiv.org/abs/2608.22479","url":"https://arxiv.org/abs/2608.22479","pdf":"https://arxiv.org/pdf/2608.22479.pdf","announceDate":"2026-08-25","title":"GTA-RAG: Graph-Trajectory-Augmented Reinforcement Learning for Multi-Turn Retrieval-Augmented Reasoning","abstract":"Retrieval-augmented generation (RAG) enables LLMs to access external knowledge for answering knowledge-intensive questions. For complex multi-hop questions, multi-turn retrieval-augmented reasoning extends RAG into an iterative process that repeatedly searches for and integrates evidence across documents. However, existing reinforcement-learning (RL) approaches for agentic RAG are typically optimized with final-answer rewards, which provide sparse supervision and overlook whether the model actually retrieves the required evidence chain. We present \\textsc{GTA-RAG}, a graph-trajectory-augmented RL framework for multi-turn retrieval-augmented reasoning. From an entity--document graph, we sample connected document paths, synthesize multi-hop QA trajectories, and validate them with the deployed retriever to obtain executable trajectory-level supervision. We then optimize the retrieval policy"},{"date":"2026-08-25","upvotes":0,"tags":["Multi-Agent","Tool Use","Reasoning","Fine-tuning","RL for LLM"],"topics":["Multi-Agent","Tool Use","Reasoning","Fine-tuning","RL for LLM","Agent Framework"],"authors":["Yalda Taheri","Mohammad Hassan Heydari","Erfan Naaman","Afsaneh Fatemi"],"source":"arxiv","id":"arxiv:2608.22472","submittedDate":"2026-08-23","arxiv":"https://arxiv.org/abs/2608.22472","url":"https://arxiv.org/abs/2608.22472","pdf":"https://arxiv.org/pdf/2608.22472.pdf","announceDate":"2026-08-25","title":"Small Reasoning Models are Instruction Followers in Function Calling","abstract":"Function calling represents the core capability of agentic large language models (LLMs). Existing research has focused on enhancing LLMs function-calling accuracy through fine-tuning, reinforcement learning (RL), and multi-agent frameworks, particularly for native function-calling LLMs. This work demonstrates that LLMs achieve superior accuracy in function calling in instruction-following contexts (i.e., standard user-assistant interactions) rather than a tool calling context. We introduce Instruction-Followed Function Calling (IFFC), a novel framework that decouples function-calling logic from the primary LLM and delegates it to a dedicated smaller model operating within the instruction-following paradigm. Our method consistently outperforms both native function calling (NFC) and prompt-based function calling (PFC) baselines, with particularly strong gains on reasoning-oriented LLMs. Fu"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Interpretability"],"topics":["Post-Training","LLM Training","Reasoning","Evaluation","Interpretability","Fine-tuning"],"authors":["Qimeng Niu","Bowen Hao","Zixuan Zhang","Shuyu Qu","Hongzhi Yin"],"source":"arxiv","id":"arxiv:2608.21939","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21939","url":"https://arxiv.org/abs/2608.21939","pdf":"https://arxiv.org/pdf/2608.21939.pdf","announceDate":"2026-08-25","title":"Enhancing Group Recommendation with Memory-Augmented Reasoning in LLM Agent","abstract":"The core challenge in group recommendation lies in modeling the dynamic evolution of user preferences and explain?ing the consensus formation process. Existing Large Language Model (LLM)-based methods, despite improved interpretability, treat interaction history as fixed text, ignoring the natural evolution of group/user preferences over time, and lacking explicit modeling of the complex group decision-making process. To address these issues, we propose AGR, a LLM-based agent, which consists of a Memory Module and a Reasoning Module. The Memory Module employs a token-based hash table to dynamically manage the historical interactions of groups and users. This design supports fundamental operations including insertion, updating, retrieval, forgetting of irrelevant records, and summarization of evolving group and user profiles for efficiently tracking. Based on these retrieved dynamic profi"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","Reasoning","Hallucination","Evaluation","Alignment"],"topics":["Post-Training","Reasoning","Hallucination","Evaluation","Alignment","RL for LLM"],"authors":["Md Asaduzzaman Jabin","Zihao Wu","Tianming Liu"],"source":"arxiv","id":"arxiv:2608.21864","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21864","url":"https://arxiv.org/abs/2608.21864","pdf":"https://arxiv.org/pdf/2608.21864.pdf","announceDate":"2026-08-25","title":"BioMed-Agent-RL: A Meta Learning, All You Need for Biomedical Applications","abstract":"The current progress of Clinical Vision Large Language Models (C-VLLMs) has substantially improved digital diagnostics, still these frameworks often endure lesion noises, modality misalignment, hallucination, and missed contextual grounding in complex clinical cases. Moreover, prevailing agent systems usually depend on static and non-adaptable pipelines and lack the versatility necessary for complex medical reasoning. To resolve these difficulties, we present BioMed-Agent-RL, a unified medical agent that incorporates adaptive orchestration, policy, and reward-based reinforcement learning (RL) models for biomedical applications. To ensure reliability, it invokes clinical context-aware preference optimization (CPO), direct preference optimization (DPO), and group relative policy optimization (GRPO) with dynamic entropy regulation. This pipeline utilizes a multimodal meta-learning approach "},{"date":"2026-08-25","upvotes":0,"tags":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation"],"topics":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation","RL for LLM"],"authors":["Suifeng Zhao","Zida Liu","Xinyu Lei","Lei Sun","Jun Gao","Sujian Li"],"source":"arxiv","id":"arxiv:2608.21808","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21808","url":"https://arxiv.org/abs/2608.21808","pdf":"https://arxiv.org/pdf/2608.21808.pdf","announceDate":"2026-08-25","title":"MCite-RL: Towards Reliable Multimodal RAG via Citation-enhanced Agentic Reinforcement Learning","abstract":"Multimodal Retrieval-Augmented Generation (RAG) with visual citation is crucial for ensuring the traceability and verifiability of MLLMs. However, current RAG and SFT-based methods struggle to achieve robust cross-modal reasoning, causing imprecise visual citations or decoupling between the citation and the generated answers. To address these limitations, we propose MCite-RL, a citation-enhanced agentic reinforcement learning framework designed for reliable multimodal RAG. MCite-RL introduces an Agentic Refinement module for visual citation that employs iterative retrieval, reasoning, and recursive cropping to progressively narrow the search space, transforming citation into a dynamic, evidence-driven reasoning process rather than a static step. Furthermore, we incorporate a Citation-enhanced Reward mechanism that integrates both process-level and outcome-level feedback within a reinforc"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","LLM Training","Tool Use","Reasoning","Fine-tuning"],"topics":["Post-Training","LLM Training","Tool Use","Reasoning","Fine-tuning","RL for LLM"],"authors":["Changjiang Jiang","Qiannian Zhao","Lei Xin","Jinxiang Xie","Preslav Nakov","Zhuohan Xie"],"source":"arxiv","id":"arxiv:2608.22429","submittedDate":"2026-08-23","arxiv":"https://arxiv.org/abs/2608.22429","url":"https://arxiv.org/abs/2608.22429","pdf":"https://arxiv.org/pdf/2608.22429.pdf","announceDate":"2026-08-25","title":"Think with Structured Grounding: Perceptual Reinforcement Learning for Chart and Visual-Tabular Understanding","abstract":"Multimodal Large Language Models (MLLMs) capable of thinking with images often rely on external tools for fine-grained perception. However, this reliance introduces significant inference latency and fails to effectively resolve the spatial-structural gap-a fundamental challenge in text-dense and structurally relational visuals (e.g., charts and visual tables) where strict relative spatial arrangements bind textual elements. Without external tools, standard MLLMs struggle with such fine-grained visual reasoning tasks. To address these issues, we propose Think with Structured Grounding (TwSG), a novel fine-grained image perception framework designed to internalize complex images's tool-use capabilities within the model. TwSG distills the benefits of multi-step reasoning and micro-cropping into a single efficient forward pass during inference. Specifically, we use an MLLM to identify key re"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","VLM Training","Reasoning","Hallucination","Evaluation"],"topics":["Post-Training","VLM Training","Reasoning","Hallucination","Evaluation","RL for LLM"],"authors":["Michael Jerge","Joseph Pelczar","Justin Downes"],"source":"arxiv","id":"arxiv:2608.21595","submittedDate":"2026-08-21","arxiv":"https://arxiv.org/abs/2608.21595","url":"https://arxiv.org/abs/2608.21595","pdf":"https://arxiv.org/pdf/2608.21595.pdf","announceDate":"2026-08-25","title":"Perturb the Thought, Not the Pixels: Latent-Space Rollout Diversification for Reinforcement Learning of Vision-Language Models","abstract":"Reinforcement learning with verifiable rewards (RLVR) improves the reasoning ability of vision-language models (VLMs), and diversifying the rollouts within each optimization group amplifies its gains. Existing approaches diversify through decoding temperature or pixel-space image distortion; we ask whether the perturbation belongs in the model's latent space instead. We introduce Noise-Contrastive GRPO (NC-GRPO), which injects scale-calibrated Gaussian noise into the last hidden layer of the prompt-encoding pass for half of each rollout group, branching those rollouts from a displaced departure state. Branches that reach the answer despite the displacement are reinforced over those derailed by it, converting sensitivity at the branch point into policy-gradient signal; the objective, reward, and inference protocol are untouched. On Qwen2.5-VL-7B trained on Geometry3K, NC-GRPO significantl"},{"date":"2026-08-25","upvotes":0,"tags":["LLM Training","Tool Use","Reasoning","Evaluation","Multimodal Agent"],"topics":["LLM Training","Tool Use","Reasoning","Evaluation","Multimodal Agent"],"authors":["Wenqi Liu","Shijie Ma","Yunxiao Wang","Meng Liu","Qile Su","Han Liu","Bohan Hou","Xuanyu Zheng","Changyi Liu","Tianke Zhang","Haonan Fan","Kaiyu Jiang","Yingxin Li","Jiankang Chen","Xu Wang","Bin Wen","Tingting Gao","Han Li","Jianhua Yin","Yinwei Wei","Xuemeng Song"],"source":"arxiv","id":"arxiv:2608.23329","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23329","url":"https://arxiv.org/abs/2608.23329","pdf":"https://arxiv.org/pdf/2608.23329.pdf","announceDate":"2026-08-25","title":"Thinking Beyond Videos: Unifying Video Reasoning and Deep Research for Open-World Video Agents","abstract":"Open-world video understanding often requires a model to locate sparse visual evidence and acquire external knowledge that is absent from the video and its parametric memory. While Thinking-with-Videos enables active temporal perception and Deep Research supports multi-step information seeking, the two capabilities are typically developed in isolation. We introduce VideoRover, a unified Video Deep Research framework that iteratively coordinates video cropping, multimodal search, and webpage browsing. Given a video-question pair, VideoRover uses each tool result to select the next action, so localized video clips guide external retrieval and retrieved evidence triggers further video inspection and verification. To develop this capability, we construct an automated data curation pipeline, producing 26K verified SFT trajectories and 3K challenging RL instances. We also introduce VideoRover-"},{"date":"2026-08-25","upvotes":0,"tags":["Multi-Agent","Reasoning","Memory","Hallucination","Evaluation"],"topics":["Multi-Agent","Reasoning","Memory","Hallucination","Evaluation"],"authors":["Sujoy Nath","Aswini Kumar","Tanmoy Chakraborty"],"source":"arxiv","id":"arxiv:2608.23152","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23152","url":"https://arxiv.org/abs/2608.23152","pdf":"https://arxiv.org/pdf/2608.23152.pdf","announceDate":"2026-08-25","title":"Counter with Evidence! A Multi-Agent Memory Efficient Reasoning Framework for Hate Category Informed Counterspeech Generation","abstract":"Counterspeech effectively neutralizes the impact of online hate. Although prior work explores automated counterspeech generation, it largely emphasizes stylistic control while treating hate speech as homogeneous, overlooking that distinct forms of abuse require fundamentally different counterspeech strategies. To address this gap, we introduce FIRE (Factuality Informed Multi-Agent Reasoning Framework) that first decomposes hate speech into one of the five distinct categories (misinformation, stereotype, conspiracy, dehumanizing, non-factual), and then maps it to a targeted counterspeech style. To facilitate FIRE, we curate FactualCS, a novel dataset of $4,784$ instances that provides the annotations regarding hate categories, reasoning traces, and evidence mappings, which are critical elements for grounded generation that are missing in prior work. A comprehensive evaluation across $28$ "},{"date":"2026-08-25","upvotes":0,"tags":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"topics":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"authors":["Yuchen Huang","Sijia Li","Jun Zhang","Yi R. Fung"],"source":"arxiv","id":"arxiv:2608.22963","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.22963","url":"https://arxiv.org/abs/2608.22963","pdf":"https://arxiv.org/pdf/2608.22963.pdf","announceDate":"2026-08-25","title":"Buried in Textual Debt: Context Pruning with Visual Evidence Preservation for MLLM Agents","abstract":"Multimodal Large Language Models (MLLMs) are increasingly deployed as multi-step agents, where explicit reasoning supports task decomposition and tool coordination but also accumulates self-generated text. Over long trajectories, this text can dominate the context and suppress visual evidence, creating textual debt. We observe that reasoning becomes redundant once task-relevant visual evidence is grounded, while stale hypotheses can misguide later inference when grounding remains uncertain. Pruning must therefore remove redundant text without discarding visual evidence. We propose SPARE, a Kullback--Leibler (KL)-guided framework for pruning accumulated reasoning in multimodal tool-use agents. SPARE uses a compact task-state summary as privileged diagnostic context. For each candidate segment, it replays the same model under the original and summary-conditioned contexts. Reverse-KL diverg"},{"date":"2026-08-25","upvotes":0,"tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"authors":["Dongsheng Chen","Tianyu Wang","Wenhui Que"],"source":"arxiv","id":"arxiv:2608.23265","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23265","url":"https://arxiv.org/abs/2608.23265","pdf":"https://arxiv.org/pdf/2608.23265.pdf","announceDate":"2026-08-25","title":"EvoWiki: Incremental State Overwriting and Traceable Question Answering for Cross-Meeting Knowledge Evolution","abstract":"In long-term collaboration spanning multiple meetings, factual states such as decisions and risks are continually revised, overturned, and replaced. Existing long-context methods typically stack the entire history, while many RAG and structured-memory methods organize knowledge as static or append-only facts and rely on semantic relevance at read time. Without explicit modeling of knowledge lifecycles, these approaches may retain conflicting old and new states simultaneously or discard history, leading to stale retrieval and answers that are difficult to verify. We present EvoWiki, an incremental question-answering architecture for dynamic long-form text. EvoWiki decouples offline incremental construction (BUILD) from online structured reading (READ). BUILD captures the intra-meeting micro-evolution from proposal to decision and uses entity version chains and a fine-grained State-Overwri"},{"date":"2026-08-25","upvotes":0,"tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"authors":["Guang Yang","Xing Hu","Xiang Chen","Terry Yue Zhuo","Xin Xia"],"source":"arxiv","id":"arxiv:2608.22938","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.22938","url":"https://arxiv.org/abs/2608.22938","pdf":"https://arxiv.org/pdf/2608.22938.pdf","announceDate":"2026-08-25","title":"Execution-Anchored Hallucination Calibration Reranking for Verilog Code Generation","abstract":"Large Language Models (LLMs) have demonstrated remarkable capabilities in code generation, yet their performance degrades significantly on low-resource Hardware Description Languages such as Verilog. While multi-candidate sampling improves the likelihood of generating correct solutions, au-tomatically selecting the optimal candidate remains an open challenge. Through a systematic empirical study across nine models and two benchmarks, we identify two critical limitations:(1) existing execution-based reranking methods, which rely on testbench pass/fail outcomes, exhibit poor domain transferability due to low-quality generated testbenches; and (2) LLM-as-a-Judge suffers from reasoning hallucination, producing incon-sistent judgments for execution-equivalent code. These findings reveal two signal types with orthogonal errors: execution signals(deterministic but testbench coverage limited)and"},{"date":"2026-08-25","upvotes":0,"tags":["Agentic Search","Post-Training","Reasoning","Alignment","RL for LLM"],"topics":["Agentic Search","Post-Training","Reasoning","Alignment","RL for LLM"],"authors":["Weichu Liu","Yuxuan Hu","Yirong Sun","Ningning Mao","Ziyun Zhang","Jian Chen","Mingyang Xu","Qishan Zhong","Chengming Li"],"source":"arxiv","id":"arxiv:2608.21925","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21925","url":"https://arxiv.org/abs/2608.21925","pdf":"https://arxiv.org/pdf/2608.21925.pdf","announceDate":"2026-08-25","title":"ESCRAG-R1: Retrieval-Augmented Reinforcement Learning for Emotional Support Conversation","abstract":"Emotional Support Conversation (ESC) systems aim to provide holistic support by balancing professional therapeutic competence with natural empathy. However, existing methods struggle to simultaneously achieve structured, stage-aware reasoning and seamless empathy-expertise alignment, often resulting in an artificial splicing of clinical strategies and generic reassurance. To overcome these limitations, we propose ESCRAG-R1, a unified framework that integrates retrieval-based psychological guidance into Group Relative Policy Optimization (GRPO). By incorporating retrieval into the reinforcement learning loop, ESCRAG-R1 transforms external knowledge into a robust learning signal that stimulates explicit internal reasoning prior to generation and fundamentally reshapes the model's internal policy. To provide the reliable supervision required for this optimization, we construct ESC-Preferenc"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Yinhao Tang","Youqing Fang","Yanan Sun","Jiangning Liu","Ziyi Wang","Xun Zhao","Weiming Zhang","Bin Liu","Kuikun Liu","Wenwei Zhang","Kai Chen"],"source":"arxiv","id":"arxiv:2608.23256","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23256","url":"https://arxiv.org/abs/2608.23256","pdf":"https://arxiv.org/pdf/2608.23256.pdf","announceDate":"2026-08-25","title":"Is Next-Chunk Reasoning RL Really Better than SFT? Revisiting Training Strategies under no-CoT Data","abstract":"Recent work proposes next-chunk reasoning RL for leveraging no-CoT data---corpora such as worked solutions and textbook derivations that contain reasoning-rich content but lack explicit chain-of-thought annotations. The method trains a model to generate implicit reasoning traces and rewards them by their ability to predict the next chunk of text. While promising, existing evaluations primarily compare against conventional SFT baselines, leaving open whether the gains come from the RL formulation itself or from more effectively exposing the model to no-CoT data. We address this question with a controlled study of next-chunk reasoning RL and a simple but previously overlooked alternative: Mixed SFT, a single supervised fine-tuning stage that jointly trains on no-CoT and long-CoT data. Despite its simplicity, Mixed SFT achieves a clearly higher post-RLVR performance ceiling than next-chunk "},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"topics":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"authors":["Yan Zhou","Sara Kangaslahti","Jonathan Geuter","Nihal V. Nayak","Marco Fumero","Francesco Locatello","David Alvarez-Melis"],"source":"arxiv","id":"arxiv:2608.22854","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.22854","url":"https://arxiv.org/abs/2608.22854","pdf":"https://arxiv.org/pdf/2608.22854.pdf","announceDate":"2026-08-25","title":"Thinking at the Right Size: Amortized Distillation Across Post-Trained LLMs","abstract":"Practical deployment of large language models (LLMs) requires families of post-trained variants---instruction-tuned, reasoning-tuned, and chat-style models---each at multiple sizes to meet diverse latency and memory budgets. Producing each (variant, size) pair independently is prohibitive, so model families typically span only a handful of coarse-grained sizes per post-trained variant. Boomerang distillation (Kangaslahti et al., 2026) reduces this cost along the size axis for base models. Through model size interpolation, it constructs models of intermediate sizes from a single teacher-student pair without additional training. However, it still treats each post-trained variant as a separate object of optimization. We introduce ADAPT---Amortized Distillation Across Post-Trained LLMs---a framework for amortizing distillation across both axes of a model family: size and post-training varian"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","VLM Training","Reasoning","Evaluation","RL for LLM"],"topics":["Post-Training","VLM Training","Reasoning","Evaluation","RL for LLM"],"authors":["Qiqian Fu"],"source":"arxiv","id":"arxiv:2608.21811","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21811","url":"https://arxiv.org/abs/2608.21811","pdf":"https://arxiv.org/pdf/2608.21811.pdf","announceDate":"2026-08-25","title":"Hints, Critics, and Teachers: Prior Injection for Sparse-Reward RL in Vision-Language Math Reasoning","abstract":"Reinforcement learning for vision-language math reasoning starves under sparse reward: on a pool of 20,830 visual-math problems where Qwen2-VL-2B answers 3.6% of rollouts correctly, 85-97% of GRPO rollout groups are entirely wrong and contribute zero gradient. We train eleven methods under identical conditions in this regime, each injecting a different prior: text (reference-solution hints), distribution (on-policy distillation from a 7B teacher), and value (a value-pretrained critic with an MSE or HL-Gauss categorical loss). A prior helps exactly when it is delivered: the six arms whose prior effectively reaches the policy separate with no overlap from the remaining five -- the no-prior baseline and four arms whose prior is teacher-capped, gated away, or lost to a mis-parameterized critic -- both on the pooled in-domain metric and on cross-domain transfer (DynaMath). The central finding"},{"date":"2026-08-25","upvotes":0,"tags":["Reasoning","Evaluation","Alignment","Interpretability","Fine-tuning"],"topics":["Reasoning","Evaluation","Alignment","Interpretability","Fine-tuning"],"authors":["Yipeng Zhao","Qishun Yang","Shenzhe Zhu","Shu Yang","Di Wang"],"source":"arxiv","id":"arxiv:2608.23497","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23497","url":"https://arxiv.org/abs/2608.23497","pdf":"https://arxiv.org/pdf/2608.23497.pdf","announceDate":"2026-08-25","title":"Mitigating Reasoning-Induced Misalignment via Safety-Direction Penalty","abstract":"Reasoning-Induced Misalignment, where fine-tuning on reasoning data containing no harmful content, including mathematics, code, and problem-solving with chain-of-thought traces can induce harmful behaviors of LLM, posing a serious challenge to the safety of LLM reasoning. Cross-architecture, cross-scale, and cross-dataset checks show that RIM does not always emerge. Previous work attributed RIM to neuron-level entanglement, but did not identify the geometry of the representation space underlying this entanglement or propose a training-time fix. We provide both: a representation-space analysis of RIM and the Safety-Direction Penalty (SDP), which penalizes movement along a learned safety direction during reasoning fine-tuning. The analysis extracts two activation-space directions, one encoding reasoning ability and the other safety behavior. These directions are coupled: fine-tuning that i"},{"date":"2026-08-25","upvotes":0,"tags":["LLM Training","Evaluation","Alignment","Fine-tuning","Data Engine"],"topics":["LLM Training","Evaluation","Alignment","Fine-tuning","Data Engine"],"authors":["Miriam Wanner","Mark Dredze","William Walden"],"source":"arxiv","id":"arxiv:2608.23476","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23476","url":"https://arxiv.org/abs/2608.23476","pdf":"https://arxiv.org/pdf/2608.23476.pdf","announceDate":"2026-08-25","title":"On the Threat Model of Weird Generalization and Emergent Misalignment","abstract":"Narrow fine-tuning on small, domain-specific datasets can produce broad and surprising changes in model behavior-a phenomenon called weird generalization (WG). Yet, it remains unclear what features of the fine-tuning data are necessary for WG to arise. Here, we address this question by investigating a range of plausibly relevant features, including dataset size, composition, language, presentation style, and novelty relative to a model's parametric knowledge. Further, since WG evaluations rely on small question sets that assess the extent of the generalization, we also analyze how sensitive this measurement is to the set of questions used. Experiments with three open-weight models on four datasets show that the degree of WG (1) depends heavily on dataset composition and language (more than on size); (2) is greater for data familiar from pretraining than for novel data; and (3) is sensiti"},{"date":"2026-08-25","upvotes":0,"tags":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"topics":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"authors":["Md. Asaduzzaman Shuvo","Ahsan Farabi","Md. Abdul Ahad Minhaz","Mahedi Hasan","Israt Khandaker","Ibrahim Khalil Shanto","Muhammad Nomani Kabir"],"source":"arxiv","id":"arxiv:2608.22950","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.22950","url":"https://arxiv.org/abs/2608.22950","pdf":"https://arxiv.org/pdf/2608.22950.pdf","announceDate":"2026-08-25","title":"WADE: A Reasoning-Annotated Benchmark for Multi-Instance Floating-Waste Grounding with Compact Vision-Language Models","abstract":"Floating waste in inland waterways threatens aquatic ecosystems and requires timely monitoring under cluttered, multi-object conditions. Existing aquatic-waste datasets provide limited geographic coverage, sparse multi-instance annotations, and little supervision beyond boxes and labels. Compact vision-language models (VLMs) therefore remain insufficiently evaluated for jointly localizing, classifying, counting, and explaining floating waste. We introduce WADE, a reasoning-annotated benchmark containing 2,167 images from rural Bangladesh, 13,608 bounding boxes, and ten waste categories. Each annotation is associated with class-level recognition rules covering visual cues, likely confusions, and discriminative features. We evaluate six VLMs under zero-shot, two-shot, reasoning-guided, and fine-tuned settings using detection, counting, and hallucination metrics. For resource-efficient adap"},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","VLM Training","Alignment","Fine-tuning","RL for LLM"],"topics":["Post-Training","VLM Training","Alignment","Fine-tuning","RL for LLM"],"authors":["Qichao Ma","Jikang Cheng","Ling Liang","Zhaofei Yu","Tiejun Huang","Renye Yan"],"source":"arxiv","id":"arxiv:2608.22780","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.22780","url":"https://arxiv.org/abs/2608.22780","pdf":"https://arxiv.org/pdf/2608.22780.pdf","announceDate":"2026-08-25","title":"Can We Perform Online RL for Image Editing without Editing Rewards?","abstract":"Reinforcement learning (RL) enables direct preference optimization for image editing through editing-specific rewards, which remain less developed due to costly triplet supervision and complex task-dependent calibration. In contrast, text-to-image (T2I) generation benefits from a mature and diverse reward ecosystem spanning semantic alignment, aesthetics, realism, glyph shape, and other visual preferences. Extending this ecosystem to image editing would substantially broaden the range of visual preferences accessible to RL-based optimization, prompting the central question: \\emph{Can We Perform Image Editing RL without Editing Rewards?} In this paper, we argue that the standard image editing dimensions have potential to be mapped to the T2I reward space: image quality can transfer directly, prompt following can be aligned through a description of the desired visual state, and reference c"},{"date":"2026-08-25","upvotes":0,"tags":["Reasoning","Memory","Reflection","Multimodal Agent"],"topics":["Reasoning","Memory","Reflection","Multimodal Agent"],"authors":["Jieke Wang","Tiancheng Shen","Yibo Yang","Ming-Hsuan Yang"],"source":"arxiv","id":"arxiv:2608.23268","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23268","url":"https://arxiv.org/abs/2608.23268","pdf":"https://arxiv.org/pdf/2608.23268.pdf","announceDate":"2026-08-25","title":"Dual-Grained Agent Memory and Shapley Context Attribution for Multimodal Agentic Learner","abstract":"Frontier multimodal large language models (MLLMs) deliver impressive perception yet still falter on scientific and mathematical reasoning. Parameter-level adaptation is unavailable for closed-weight or on-device backbones, and stateless prompting forfeits any compounding benefit from problems already solved. We propose \\textbf{DG-Mem}, a dual-grained agentic memory framework that augments a frozen MLLM with a non-parametric, externally stored memory built once from training-time rollouts and consulted read-only at test time. Motivated by the Complementary Learning Systems (CLS) account of human memory, DG-Mem factors its store into an instance-grounded exemplar memory and a category-level schema memory of IF-THEN rules, with a transient reflection store mediating their construction so that schemas are synthesized only from abstract reflections, never from exemplar text. Two design choice"},{"date":"2026-08-25","upvotes":0,"tags":["Tool Use","Planning","Evaluation","Agent Framework"],"topics":["Tool Use","Planning","Evaluation","Agent Framework"],"authors":["Jiatong Li","Wengyu Zhang","Weida Wang","Yuxuan Ren","Wei Liu","Chenyang Mao","Yuqiang Li","Yatao Bian","Changmeng Zheng","Xiaoyong Wei","Qing Li"],"source":"arxiv","id":"arxiv:2608.23104","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23104","url":"https://arxiv.org/abs/2608.23104","pdf":"https://arxiv.org/pdf/2608.23104.pdf","announceDate":"2026-08-25","title":"Molecular LLM Agents: From Architectural Design to Scientific Autonomy","abstract":"Molecular science represents an important frontier for LLM-based agents. Unlike general agents that mainly operate over natural language, code, or web environments, molecular LLM agents must perceive, reason about, and act upon chemical objects across symbolic strings, molecular graphs, 3D conformations, spectra, simulations, and wet-lab measurements. Their capabilities depend on chemically faithful molecular perception, an LLM-centered agent framework, domain-specific tool grounding, and computational or experimental feedback, in addition to planning and tool use. This work develops a conceptual framework for molecular LLM agents from two complementary perspectives. First, we introduce an architectural view of molecular-agent design, covering molecular representation and perception, the agent framework, domain-specific toolboxes, and learning and optimization. Second, we propose a scien"},{"date":"2026-08-25","upvotes":0,"tags":["Multi-Agent","Tool Use","Planning","Evaluation"],"topics":["Multi-Agent","Tool Use","Planning","Evaluation"],"authors":["Yi Zhu","Xiongwei Wu","Qiyi Wang","Tingyu Qu","Jiajun Liu","Sihan Cao","Long Chen","Weigao Sun","Feida Zhu","Yiran Zhong","Steven Hoi"],"source":"arxiv","id":"arxiv:2608.23035","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.23035","url":"https://arxiv.org/abs/2608.23035","pdf":"https://arxiv.org/pdf/2608.23035.pdf","announceDate":"2026-08-25","title":"MobilePA-Bench: Benchmarking Mobile Planner Agents on Complex Real-World Tasks","abstract":"As on-device LLM agents evolve into personal copilots, the mobile operating system has become a key testbed for this paradigm, making rigorous capability evaluation essential. Yet existing benchmarks fall into two camps, each with a critical blind spot: GUI-centric benchmarks test surface-level screen manipulation while overlooking background tool use and long-horizon planning, whereas static function-calling benchmarks rely on offline API matching that is detached from real runtime constraints. To close this gap, we present \\textbf{MobilePA-Bench}, an interactive, stateful, and tool-centric benchmark for evaluating the tool-calling and planning abilities of mobile planning agents. MobilePA-Bench runs on an executable sandbox that maintains live application databases and returns structured feedback, spanning $13$ functional domains and $212$ realistic mobile tools. Beyond basic tool use,"},{"date":"2026-08-25","upvotes":0,"tags":["VLM Training","Computer Use","Evaluation","Data Engine"],"topics":["VLM Training","Computer Use","Evaluation","Data Engine"],"authors":["Long Zhang","Yuhan Chen","Chaoran Zhang","Wanxia Cao","Kun Huang","Pengzhi Gao","Wei Liu","Jian Luan","Chenliang Li","Lixin Zou"],"source":"arxiv","id":"arxiv:2608.22847","submittedDate":"2026-08-24","arxiv":"https://arxiv.org/abs/2608.22847","url":"https://arxiv.org/abs/2608.22847","pdf":"https://arxiv.org/pdf/2608.22847.pdf","announceDate":"2026-08-25","title":"GSAR: Goal-State-Anchor Rewards for Mobile GUI Agents with Self-Evolving Data Synthesis","abstract":"Vision-Language Models (VLMs) based GUI agents stand to benefit significantly from online reinforcement learning (RL). However, their training is bottlenecked by two fundamental issues: current data synthesis methods for GUI Agents rely on specific environments and struggle to generate diverse data, while existing evaluators either suffer from limited scalability or provide inaccurate and unreliable reward signals. To overcome these challenges, we introduce GSAR (Goal-State-Anchor Reward), a RL reward framework that supports scalable task generation and delivers reliable reward signals for stable and efficient policy optimization. Our approach features self-evolving data synthesis, which produces multiple environments through task execution and generates diverse tasks and goal states. Complementing this, a state-anchor mechanism automatically annotates task-relevant UI elements in succes"},{"date":"2026-08-25","upvotes":0,"tags":["Agent Safety","Reasoning","Evaluation","Alignment"],"topics":["Agent Safety","Reasoning","Evaluation","Alignment"],"authors":["Isotta Magistrali","Chen Shani"],"source":"arxiv","id":"arxiv:2608.22444","submittedDate":"2026-08-23","arxiv":"https://arxiv.org/abs/2608.22444","url":"https://arxiv.org/abs/2608.22444","pdf":"https://arxiv.org/pdf/2608.22444.pdf","announceDate":"2026-08-25","title":"Aligned Alone, Misaligned Together: Forecasting Adversarial Capture in LLM Agent Populations","abstract":"The unit of AI safety evaluation is still the individual model, yet language-model agents are increasingly deployed in interacting populations that read and write one another's decisions. This raises a question no single-agent audit can answer: an agent that is well-calibrated on its own may still be pulled toward a different decision by the agents around it. We study this on a security-triage task, where populations of language-model monitors decide whether to escalate or dismiss alerts, and into which we can inject a committed minority that always pushes one way. We find that two alerts a single agent judges almost identically on its own can drive collective behavior far apart, so auditing any one member need not reveal what the population will do. Yet that collective behavior can be predicted in advance. From a population's benign, adversary-free operation alone, we calibrate a respon"},{"date":"2026-08-25","upvotes":0,"tags":["Agentic RAG","Post-Training","Reasoning","Evaluation"],"topics":["Agentic RAG","Post-Training","Reasoning","Evaluation"],"authors":["Zhaohan Meng","Zaiqiao Meng","Siwei Liu","Hao Xu","Ke Yuan","Iadh Ounis"],"source":"arxiv","id":"arxiv:2608.22132","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.22132","url":"https://arxiv.org/abs/2608.22132","pdf":"https://arxiv.org/pdf/2608.22132.pdf","announceDate":"2026-08-25","title":"SSE-Bio: A Structured Self-Evolving Agent with Agentic Retrieval Policy for Multi-Hop Biomedical Reasoning","abstract":"Biomedical multi-hop question answering (QA) requires models to connect evidence across intermediate entities such as diseases, drugs, proteins, and phenotypes. Existing agents typically rely on static retrieval workflows or coarse-grained prompt rewriting, which can lead to instruction drift when reasoning procedures need to be updated. We propose SSE-Bio, a structured self-evolving agent with an agentic retrieval policy for multi-hop biomedical reasoning. Instead of globally rewriting agent instructions, SSE-Bio maintains a structured state, selectively retrieves knowledge triplets and prior templates through a trainable proxy policy, and improves its reasoning memory through fine-grained template editing. To optimise retrieval decisions, we introduce a proxy-training strategy based on group relative policy optimization, where the proxy is improved through decision-contrastive groups o"},{"date":"2026-08-25","upvotes":0,"tags":["Tool Use","Reasoning","Evaluation","RL for LLM"],"topics":["Tool Use","Reasoning","Evaluation","RL for LLM"],"authors":["Yucan Guo","Xiaohan Wang","Miao Su","Saiping Guan","Zhongni Hou","Jiajun Chai","Wei Lin","Guojun Yin","Xiaolong Jin","Jiafeng Guo","Xueqi Cheng"],"source":"arxiv","id":"arxiv:2608.21863","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21863","url":"https://arxiv.org/abs/2608.21863","pdf":"https://arxiv.org/pdf/2608.21863.pdf","announceDate":"2026-08-25","title":"HiDiffTIR: Hierarchical Difficulty-Aware Policy Optimization for Multi-Turn Tool-Integrated Reasoning","abstract":"Tool-Integrated Reasoning (TIR) is a fundamental capability for LLM agents to solve complex tasks by interacting with external tools iteratively. Reinforcement Learning (RL) has become the dominant paradigm for enabling this capability. However, existing approaches typically assign uniform trajectory-level advantages and treat all correct tool calls equally, ignoring the varying difficulty and learning value across trajectories and reasoning steps. This can lead to imprecise learning signals that do not adequately distinguish between trivial and challenging tool-use patterns. To address this limitation, we propose HiDiffTIR, a Hierarchical Difficulty-aware policy optimization framework for multi-turn TIR. HiDiffTIR performs difficulty-aware credit assignment at both trajectory and turn levels, enabling the policy to focus on more informative trajectories and harder reasoning steps. Notab"},{"date":"2026-08-25","upvotes":0,"tags":["VLM Training","Reasoning","Evaluation","Alignment"],"topics":["VLM Training","Reasoning","Evaluation","Alignment"],"authors":["Md Abrar Jahin","Md Rizwan Parvez"],"source":"arxiv","id":"arxiv:2608.21832","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21832","url":"https://arxiv.org/abs/2608.21832","pdf":"https://arxiv.org/pdf/2608.21832.pdf","announceDate":"2026-08-25","title":"GUI-Primitives: Diagnosing Spatial Reasoning Failures in Vision-Language GUI Grounding","abstract":"Computer-use agents ground natural-language instructions in screenshots to locate interface elements, yet existing benchmarks do not isolate whether models bind relational language to the correct element. We introduce GUI-Primitives, a 994-item benchmark of contrastive instruction pairs over seven spatial relations in graphical user interfaces (left/right, above/below, containment, alignment, proximity, list ordinal, occlusion). Each pair holds the screenshot and anchor fixed while changing the relation expression, so the correct target moves between two designated candidates. Five annotators validate a 196-item subset ($κ= 0.94$ well-formedness; $κ= 0.79$ target selection). Nineteen vision-language models reach at most $32\\%$ strict point-in-box accuracy. Because models emit unconstrained coordinates, we classify each prediction by the candidate region it falls within. Predictions fall "},{"date":"2026-08-25","upvotes":0,"tags":["Post-Training","Computer Use","Evaluation","Alignment"],"topics":["Post-Training","Computer Use","Evaluation","Alignment"],"authors":["Chengyang Gu","Le Zhang","Jingbo Zhou","Yize Chen","Yu Shi","Siqi Bao","Zheng-Fan Wu","Hua Wu","Hui Xiong"],"source":"arxiv","id":"arxiv:2608.21830","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21830","url":"https://arxiv.org/abs/2608.21830","pdf":"https://arxiv.org/pdf/2608.21830.pdf","announceDate":"2026-08-25","title":"Beyond Success and Failure: Length-Aware Contrastive Learning for GUI Agents","abstract":"Graphical User Interface (GUI) agents powered by Multimodal Large Language Models (MLLMs) have shown strong potential for automating tasks across diverse digital environments, where reinforcement learning (RL) has become a dominant training paradigm. However, widely used methods such as Group Relative Policy Optimization (GRPO) suffer from reward-gradient misalignment, leading to inefficient and unstable optimization. Recent work addresses this issue by reformulating RL with verifiable rewards (RLVR) as contrastive or classification-based objectives, which improve stability by eliminating problematic gradient behaviors. Despite this progress, existing contrastive RLVR methods rely primarily on outcome-level supervision and fail to capture fine-grained differences in trajectory quality within the same outcome category. In this paper, we propose Length-Aware Contrastive Learning for GUI Ag"},{"date":"2026-08-25","upvotes":0,"tags":["LLM Training","Multi-Agent","Evaluation","Fine-tuning"],"topics":["LLM Training","Multi-Agent","Evaluation","Fine-tuning"],"authors":["Deyi Li","Qi Xu","Lingyao Li","Tiansheng Wang","Muxuan Liang","Mei Liu"],"source":"arxiv","id":"arxiv:2608.21712","submittedDate":"2026-08-22","arxiv":"https://arxiv.org/abs/2608.21712","url":"https://arxiv.org/abs/2608.21712","pdf":"https://arxiv.org/pdf/2608.21712.pdf","announceDate":"2026-08-25","title":"ATHENA: Knowledge-guided agentic neural architecture search for AutoFormer-based electronic health record modeling","abstract":"Transformer-based models are widely used for clinical prediction from electronic health records (EHRs), yet their architectures still require substantial manual tuning, and the optimal configuration may vary across tasks and hospitals. Neural architecture search (NAS) automates architecture design, but conventional methods are computationally costly for Transformer-based EHR models. Recent large language model (LLM)-guided NAS methods reduce manual search design but typically conduct each search independently, without reusing architecture knowledge across hospitals. In this study, we propose ATHENA (Agentic Transfer across Hospitals for EHR Neural Architecture Search), a knowledge-guided agentic NAS framework for Transformer-based EHR modeling. ATHENA uses a weight-sharing supernet that is pretrained once per hospital, allowing candidate architectures to be instantiated as inherited subn"}],"archive":[],"latestPath":"data/latest.json"};
